using System.Text.Json.Nodes;

namespace MySummerRemake.SaveMaster.Core;

public sealed record FastenerCatalogEntry(string Id, int MaximumStage, int SizeMillimeters, bool RequiredForRemoval);
public sealed record MountCatalogEntry(string Id, string[] Fasteners, string[] GroupIds, int MaximumTightness, int OnThreshold, int OffThreshold, string[] AcceptedParts, string OwnerPart);

/// <summary>Scalar snapshot of project-owned FastenerDefinition/MountPointDefinition authoring.
/// Source paths and SHA-256 are retained in the data for audit. No donor binary content.</summary>
public static class SchemaVehicleDefinitions
{
    public static IReadOnlyDictionary<string, FastenerCatalogEntry> Fasteners { get; }
    public static IReadOnlyDictionary<string, MountCatalogEntry> Mounts { get; }
    static SchemaVehicleDefinitions()
    {
        JsonObject source = JsonNode.Parse(Data)!.AsObject();
        Fasteners = source["bolts"]!.AsArray().Select(n => new FastenerCatalogEntry(
            (string)n!["id"]!, (int)n["max"]!, (int)n["size"]!, (bool)n["required"]!)).ToDictionary(x => x.Id, StringComparer.Ordinal);
        Mounts = source["mounts"]!.AsArray().Select(n => new MountCatalogEntry(
            (string)n!["id"]!, Strings(n["fasteners"]), Strings(n["groupIds"]), (int)n["max"]!,
            (int)n["on"]!, (int)n["off"]!, Strings(n["accepted"]), (string)n["owner"]!)).ToDictionary(x => x.Id, StringComparer.Ordinal);
    }
    private static string[] Strings(JsonNode? node) => node!.AsArray().Select(n => (string)n!).ToArray();
